/**
 * Fix I (SFCC-236, click-passthrough) — behavioural coverage for `handleMediaClick` (index.tsx).
 * Lifting ZimmProductCardMedia above the stretched-link overlay (this recipe's own Fix I, see the
 * "real recipe assertions" block below) fixes the touch-swipe bug but means a plain click on the
 * image no longer reaches that overlay `<a>` — this organism now navigates via
 * `useHistory().push(href)` itself, guarded so the two arrow buttons and the remove/close button
 * (all real <button> descendants of Media) keep doing only their own thing. Same "necessary, not
 * sufficient" caveat as the "KNOWN LIMITATION" docblock above: this proves the CALLBACK WIRING
 * (does the right handler fire, with the right argument, for the right target), not that a real
 * touch swipe geometrically avoids triggering it — that half needs the real-device/Playwright
 * check the plan's own verification section calls for; jsdom performs no real drag-vs-tap
 * distinction to test against.
 */
describe('ZimmProductCard — Fix I: media click passthrough navigates to href, buttons keep their own behaviour', () => {
  beforeEach(() => {
    mockHistoryPush.mockClear();
  });

  test('clicking the image (not a button) navigates via history.push to the card’s href', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
    await user.click(screen.getByRole('img', { name: PRIMARY.alt }));
    expect(mockHistoryPush).toHaveBeenCalledTimes(1);
    expect(mockHistoryPush).toHaveBeenCalledWith('/product/1');
  });

  // Fix L (CodeRabbit finding on PR #85, verified correct before fixing): a real <a> lets the
  // browser handle a modifier-click or non-primary-button click natively (new tab/window) instead
  // of forcing an in-page navigation — history.push must never fire for any of these, only for a
  // plain, unmodified, primary-button click (already covered above). `fireEvent` (not
  // `userEvent`) is used here deliberately: this asserts the handler's own raw event-property
  // branching (event.metaKey/ctrlKey/shiftKey/altKey/button), not a realistic user gesture.
  test.each([
    ['Cmd/Meta-click', { metaKey: true }],
    ['Ctrl-click', { ctrlKey: true }],
    ['Shift-click', { shiftKey: true }],
    ['Alt-click', { altKey: true }],
    ['a non-primary-button click (e.g. middle-click)', { button: 1 }],
  ])('%s on the image does NOT navigate', (_label, eventInit) => {
    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
    fireEvent.click(screen.getByRole('img', { name: PRIMARY.alt }), eventInit);
    expect(mockHistoryPush).not.toHaveBeenCalled();
  });

  test('clicking a carousel arrow pages the gallery and does NOT navigate', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('plp')} images={GALLERY} />);
    mockScrollTo();
    await user.click(screen.getByRole('button', { name: 'Next image' }));
    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
    expect(mockHistoryPush).not.toHaveBeenCalled();
  });

  test('clicking the remove (close) button removes from wishlist and does NOT navigate', async () => {
    const onRemove = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onRemove={onRemove} />);
    await user.click(screen.getByRole('button', { name: 'Remove Natura Dress from wishlist' }));
    expect(onRemove).toHaveBeenCalledTimes(1);
    expect(mockHistoryPush).not.toHaveBeenCalled();
  });
});

